package com.hrflow.platform;
import com.hrflow.platform.security.JwtService; import com.hrflow.platform.user.*; import org.junit.jupiter.api.Test; import java.time.Duration; import static org.assertj.core.api.Assertions.*;
class JwtServiceTest { @Test void generatesAndValidatesSignedToken(){JwtService jwt=new JwtService("a-secure-test-secret-that-is-longer-than-32-bytes",Duration.ofMinutes(5));User u=new User();u.setEmail("person@example.com");u.setRole(Role.HR);String token=jwt.generate(u);assertThat(jwt.subject(token)).isEqualTo("person@example.com");assertThat(jwt.valid(token,u.getEmail())).isTrue();assertThat(jwt.valid(token,"other@example.com")).isFalse();}@Test void rejectsWeakSecret(){assertThatThrownBy(()->new JwtService("weak",Duration.ofHours(1))).isInstanceOf(IllegalStateException.class);}}
